return {
  [ [[v5748eaic9neh]] ] = { t = [[法术扩展与线形法术]], q = [[法术扩展专长如何影响线形效果的法术？]], a = [=[按规则字面，没有任何影响——线形没有宽度这一维度，所以无法被本专长加倍；而且大多数线形法术的射程是固定的，除非使用[[法术增远]]，否则法术无法超出这一射程。因此对大多数线形法术来说，除非同时搭配法术增远，法术扩展不起任何作用。是的，这很奇怪，我们以后也许会重新审视这条规则。

不过，作为一条房规（并非规则的官方更新），允许某人对线形法术使用法术扩展专长，并真的把它的射程加倍，是合理的。毕竟你把环位提高了3环，如果你是以6环法术施放[[闪电束]]，至少应该能得到一道240尺长的闪电。]=], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9neh]], cat = [[FAQ]], ai = false, pages = { [[法术扩展]] } },
  [ [[v5748eaic9tl1]] ] = { t = [[野性护甲与变形装备]], q = [[当我使用野性护甲并获得护甲的益处时，我会受到哪些限制（如果有的话）？更一般地说，当我通过变形效果变身、部分装备融入变身后的形态时，融合大量沉重装备会受到什么限制？其他类型的变形护甲又如何？]], a = [=[如果你在变形之前就因负重而处于中载或重载，你在融合后的形态下仍会承受这些减值。否则，忽略融合物品的重量，完全按照未融合的物品来计算你变形后形态的负重。穿着融合的护甲和盾牌时，如果你没有从融合的护甲中获得任何益处，你仍然算作穿着该类型的护甲，但不承受它的防具检定减值、移动速度降低或奥术失败率。如果你确实获得了任何益处（如具有野性能力的情形），那么你就要承受防具检定减值、移动速度降低和奥术失败率。这同样适用于你或护甲发生变形的所有其他情形：你始终算作穿着该类型的护甲；只要你从护甲中获得了任何益处（如[[雾纺软甲]]），你就要承受防具检定减值、移动速度降低和奥术失败率。]=], book = [[核心规则书]], date = [[2015/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9tl1]], cat = [[FAQ]], ai = true, pages = { [[野性]] } },
  [ [[v5748eaic9o2u]] ] = { t = [[奥术联结与侦测魔法]], q = [=[你能否用[[侦测魔法]]或类似效果，识别出作为法师奥术联结对象的物品，即使这件物品没有任何其他附魔？]=], a = [[既然奥术联结职业能力在与物品相连时，赋予法师施放任意一个法术的能力，那么可以放心地认为，当它成为侦测魔法的目标时，确实会散发魔法灵光。灵光强度直接取决于它所能施放的最高环级法术；但除非该物品另外被附魔，否则它不会有任何关联学派。]], book = [[核心规则书]], date = [[2011/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o2u]], cat = [[FAQ]], ai = true, pages = { [[法师]] } },
  [ [[v5748eaic9o81]] ] = { t = [[遣散魔宠]], q = [=[我能遣散我的[[魔宠]]，以便选择一只新魔宠吗？]=], a = [=[规则中并没有对此做出说明，但是可以：若你想选择新魔宠，你应当能够遣散现有的魔宠。不过，你仍须等待1周，并为那个8小时的仪式支付200gp。遣散魔宠即是切断你的灵魂与它之间的纽带，所以这大概需要1小时左右。

上述情形的例外是你选取了[[进阶魔宠]]专长：它允许你立刻用新魔宠替换原有魔宠，无需花费金钱或时间（默认这发生在你升级时所做的各种准备之中）。

魔宠一经遣散，动物魔宠就只是同类型的普通动物（通过进阶魔宠专长获得的特殊魔宠则恢复为同类型的普通生物）。它是否愿意继续留在你身边，由GM决定，大概取决于它做你的魔宠时你是如何对待它的。]=], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o81]], cat = [[FAQ]], ai = false, pages = { [[法师]], [[进阶魔宠]] } },
  [ [[v5748eaic9t91]] ] = { t = [[狂暴]], q = [=[如果我正处于狂暴、[[掉链野蛮人|掉链狂暴]]、血怒或类似的狂暴形式中，我能叠加尽可能多的益处吗？]=], a = [=[不能。当你启动一种新形式的狂暴，或受到其影响时（例如[[野蛮人]]的狂暴、[[歌者]]的战怒之歌、[[血脉狂怒者]]的血怒，以及[[狂暴术]]），你可以选择保留当前的狂暴，或改为接受新的狂暴，这与受到多个变形效果影响的生物类似。如果你正处于一种无法自行自动结束的狂暴之中，例如[[凶暴蛮者]]的失控狂暴，你就不能选择用新的狂暴效果取而代之。这条规则的例外是歌者的歌者大师能力，它明确允许歌者的战怒之歌与其他狂暴效果叠加。]=], book = [[进阶职业指南]], date = [[2015/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gw#v5748eaic9t91]], cat = [[FAQ]], ai = true, pages = { [[野蛮人]], [[血脉狂怒者]], [[歌者]] } },
  [ [[v5748eaic9tml]] ] = { t = [[龙脉术士与血脉狂怒者]], q = [=[[[龙脉术士]]的龙之血脉能力会增强龙族血统[[术士]]的血统能力。那么龙裔血脉的[[血脉狂怒者]]呢？]=], a = [[是的，龙脉术士的龙之血脉能力也应当增强龙裔血脉狂怒者的狂血之力。]], book = [[进阶职业指南]], date = [[2015/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gw#v5748eaic9tml]], cat = [[FAQ]], ai = false, pages = { [[龙脉术士]], [[血脉狂怒者血脉/龙裔血脉]] } },
  [ [[v5748eaic9ux4]] ] = { t = [[血脉狂怒者的血脉与术士物品]], q = [=[血脉狂怒者能否使用那些要求术士等级、并与术士血统相关的能力，比如[[奥术传承之袍]]？]=], a = [=[不能。有些混合职业，如[[拳师]]，有一项职业特性允许它们使用与其源职业相关的物品，但血脉狂怒者没有。]=], book = [[进阶职业指南]], date = [[2016/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gw#v5748eaic9ux4]], cat = [[FAQ]], ai = true, pages = { [[血脉狂怒者]], [[奥术传承之袍]] } },
