  [ [[v5748eaic9u2c]] ] = { t = [[兽群围猎]], q = [[兽群围猎是战斗专长吗？]], a = [[是的，兽群围猎应当是战斗专长。这一改动会在下一次勘误中体现。]], book = [[进阶职业指南]], date = [[2015/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gw#v5748eaic9u2c]], cat = [[FAQ]], ai = false, pages = { [[兽群围猎]] } },
